head.script:
scwin.onpageload = function() {
	var c_cnt = 8;
	var c_subName = "windowContainer_controlIconFormatter_WESD-435_(WSQ-4584)_sub";
	for (var i = 0; i < c_cnt; i++) {
		windowContainer1.createWindow(c_subName + i, null, '/sample/common_link/windowContainer_controlIconFormatter_WESD-435_(WSQ-4584)_sub0.xml', "", null, "existWindow", null, null);
	}
};

